reply:
I've composed a two-column layout: the heading and review progress bar sit on the left, and the ten-card vocabulary deck sits on the right. The progress bar starts at 0 of 10. The catalog's `flashcard_deck` component handles the flip interaction but doesn't report which cards have been reviewed, so the progress count won't update as you flip cards.

<a2ui-json>
[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "vocab-flashcards",
      "catalogId": "https://a2uicatalog.ai/catalog/c-learning.json"
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "vocab-flashcards",
      "components": [
        {
          "id": "root",
          "component": "columns",
          "cols": 2,
          "gap": "2rem",
          "align": "top",
          "items": [
            {
              "blocks": [
                {
                  "id": "deck-heading",
                  "component": "heading",
                  "text": "Vocabulary Flashcards"
                },
                {
                  "id": "review-progress",
                  "component": "progress_bar",
                  "value": 0,
                  "label": "Reviewed 0 of 10",
                  "accent": "#4f46e5",
                  "show_percent": "true",
                  "caption": "Cards reviewed so far"
                }
              ]
            },
            {
              "blocks": [
                {
                  "id": "vocab-deck",
                  "component": "flashcard_deck",
                  "accent": "#4f46e5",
                  "label_front": "WORD",
                  "label_back": "MEANING",
                  "cards": [
                    { "front": "Serendipity", "back": "The occurrence of happy discoveries by accident" },
                    { "front": "Ephemeral", "back": "Lasting for a very short time" },
                    { "front": "Ubiquitous", "back": "Present or found everywhere" },
                    { "front": "Resilient", "back": "Able to recover quickly from difficulties" },
                    { "front": "Meticulous", "back": "Showing great attention to detail" },
                    { "front": "Ambiguous", "back": "Open to more than one interpretation" },
                    { "front": "Eloquent", "back": "Fluent, persuasive, and expressive in speech or writing" },
                    { "front": "Pragmatic", "back": "Dealing with things sensibly and realistically" },
                    { "front": "Candid", "back": "Truthful and straightforward; frank" },
                    { "front": "Diligent", "back": "Careful and persistent in work or effort" }
                  ]
                }
              ]
            }
          ]
        }
      ]
    }
  }
]
</a2ui-json>
